```csharp
static IEnumerable<int> Fibonacci()
{
    int a = 0, b = 1;
    while (true)
    {
        yield return a;
        (a, b) = (b, a + b);
    }
}

int count = 0;
foreach (int f in Fibonacci())
{
    Console.WriteLine(f);
    if (++count == 10) break;
}
```
